SELECT s.id, s.name AS stationName, s.location_name AS address, s.price AS defaultPrice, s.price_type AS priceType, s.status, s.auth_status AS authStatus, s.create_time AS createTime, s.owner_id AS ownerId, u.username AS ownerUsername, u.name AS ownerName, u.phone AS ownerPhone FROM private_charge_station s LEFT JOIN user_info u ON s.owner_id = u.id WHERE s.is_deleted = 0
AND s.auth_status = #{authStatus}
ORDER BY s.create_time DESC

SELECT s.id, s.name, s.location_name as locationName, s.longitude, s.latitude, s.price, s.price_type as priceType, s.status, s.type, s.current_type as currentType, s.max_charge_power as maxChargePower, s.open_status as openStatus, s.auth_status as authStatus, s.owner_id as ownerId, s.rating, s.image, s.create_time as createTime, u.name as ownerName, u.phone as ownerPhone FROM private_charge_station s LEFT JOIN user_info u ON s.owner_id = u.id WHERE s.is_deleted = 0
AND s.name LIKE CONCAT('%', #{query.name}, '%')
AND s.status = #{query.status}
AND s.auth_status = #{query.authStatus}
AND s.type = #{query.type}
AND s.open_status = #{query.openStatus}
AND s.owner_id = #{query.ownerId}
AND s.price_type = #{query.priceType}
ORDER BY s.create_time DESC LIMIT #{offset}, #{limit}

